FLAG = {r['st']: r for r in csv.DictReader(open(os.path.join(HERE, 'work/flagger_by_state.tsv')), delimiter='\t')}
TAIL = " Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs."
T_STATE = 'Traffic control: which manual applies and flagger cards'
T_FINE = 'Traffic control: work zone speed and fines'
T_FLAG = 'Traffic control: flaggers'
T_TAPER = 'Traffic control: tapers and buffer spaces'
T_SIGN = 'Traffic control: advance warning signs'
T_TA = 'Traffic control: typical setups for utility work'

S = []
def st(id, state, title, topic, text, src, url, edition=None, effective=None, tier='core', conf='high', lic='summary', unc=False, note=None):
    c = dict(id=id, state=state, tier=tier, title=title, topic=topic, text=text, source=src, url=url, checked='2026-11-20',
             confidence=conf, kind='summary', license=lic)
    if edition: c['edition'] = edition
    if effective: c['effective'] = effective
    if unc: c['unconfirmed'] = 'yes'
    if note: c['note'] = note
    S.append(c)

def flag_sentence(code):
    f = FLAG.get(code)
    if not f:
        return (" Flagger card rule: not confirmed for " + NAMES[code] + ". The national MUTCD only says flaggers should be trained (Section 6D.01); ask the state DOT or the agency that issued the permit which flagger course it accepts.", None)
    t = " Flaggers: " + f['req'].rstrip('.') + "."
    if f['validity']: t += " How long it lasts: " + f['validity'] + "."
    if f['accepted'] and f['accepted'] not in f['req']: t += " Accepted: " + f['accepted'] + "."
    t += " (" + f['source'] + ".)"
    return (t, f)

PRIMARY_FLAG = {'WA', 'OR', 'CA', 'CO'}
for code, name in NAMES.items():
    a = ADOPT.get(code)
    ft, f = flag_sentence(code)
    if code == 'CA':
        ft = " Flaggers: the CA MUTCD makes training a requirement. Flaggers shall be trained in the fundamentals of flagging moving traffic before they are assigned (Section 6D.01, a California Standard), following Cal/OSHA Construction Safety Orders section 1599, with training records kept under the employer's Injury and Illness Prevention Program (8 CCR 3203). The state does not issue a flagger card."
    if code == 'WA':
        ft = " Flaggers: every flagger must carry a valid state traffic control flagger card, with an expiration date no more than 3 years from issue, under WAC 296-155-305(6); the WSDOT Standard Specifications (1-10.3(1)A) say the same. Someone without a card may flag only in an emergency, until a certified flagger takes over. Cards from the reciprocity states are accepted: Oregon, Idaho and Montana."
    unc = False
    if a:
        lead = a['s']; src = a['src']; url = a['url']; ed = a.get('ed'); eff = a.get('eff')
        unc = (not a['p']) or a.get('unc', False)
        conf = 'high' if (a['p'] and not unc and code in {'CA', 'WA', 'OR'}) else 'medium'
        if code in ('AZ', 'FL'):
            ft, f = flag_sentence('__none__') if False else (" Flagger card rule: not confirmed for " + name + " from a state source read here. The national MUTCD says flaggers should be trained (Section 6D.01); " + ("FDOT runs a Temporary Traffic Control (MOT) training program with a flagger course, so ask FDOT or the permit office which card it wants." if code == 'FL' else "ask ADOT or the city that issued the permit which flagger course it accepts."), None)
            unc = True; conf = 'medium'
    else:
        k = KITMAP.get(code)
        if code == 'DC':
            lead = "District of Columbia: which MUTCD edition DDOT has in force was not confirmed here; ask DDOT's public space permit office."
        else:
            lead = f"{name}: an industry tracker lists the state as one that {KIT[k]}, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force." + EXTRA.get(code, '')
        unc = True
        src = (f['source'] if f else 'MUTCD 11th Edition Section 6D.01 (national)') + '; adoption status not confirmed'
        url = wz(f['wz_url_n']) if f else 'https://mutcd.fhwa.dot.gov/resources/state_info/index.htm'
        ed = (f['source'].split(';')[0] + ', as posted ' + f['wz_modified']) if f else 'MUTCD 11th Edition, December 2023 (state status not confirmed)'
        eff = None
        conf = 'medium' if f else 'low'
    if f and code not in PRIMARY_FLAG and 'not confirmed' not in ft:
        ft += " This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on " + f['wz_modified'] + "; confirm it in the current spec book before you rely on it."
    tail = TAIL
    if code == 'CA': tail = " California prints its own tables: sign spacing by speed in Table 6B-1 and 12 ft taper lengths in Table 6B-3(CA) of the CA MUTCD; the taper formula is the national one, L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan or encroachment permit governs."
    if code == 'OR': tail = " Taper, cone and sign spacing tables for short jobs are in the handbook (Tables 2-1 to 2-4); the taper formula is the national one. The approved traffic control plan governs."
    text = lead + ft + tail
    if len(text) > 1200: text = lead + ft + " Tapers and spacing follow the national MUTCD Part 6 unless the state manual or permit says otherwise. The approved traffic control plan governs."
    st(f'tc-{code.lower()}-adopt-1', code, f'{name} traffic control: which MUTCD applies and the flagger training rule', T_STATE, text, src[:300], url, ed, eff, conf=conf,
       lic='summary', unc=unc)

